INSERT INTO `abilities` VALUES (1,'Overgrow','Strengthens Grass moves to inflict 1.5× damage at 1/3 max HP or less.'),(2,'Chlorophyll','Doubles Speed during strong sunlight.'),(3,'Blaze','Strengthens Fire moves to inflict 1.5× damage at 1/3 max HP or less.'),(4,'Solar Power','Increases Special Attack to 1.5× but costs 1/8 max HP after each turn during strong sunlight.'),(5,'Torrent','Strengthens Water moves to inflict 1.5× damage at 1/3 max HP or less.'),(6,'Rain Dish','Heals for 1/16 max HP after each turn during rain.'),(7,'Shield Dust','Protects against incoming moves\' extra effects.'),(8,'Run Away','Ensures success fleeing from wild battles.'),(9,'Shed Skin','Has a 33% chance of curing any major status ailment after each turn.'),(10,'Compound Eyes','Increases moves\' accuracy to 1.3×.'),(11,'Tinted Lens','Doubles damage inflicted with not-very-effective moves.'),(12,'Swarm','Strengthens Bug moves to inflict 1.5× damage at 1/3 max HP or less.'),(13,'Sniper','Strengthens critical hits to inflict 3× damage rather than 2×.'),(14,'Keen Eye','Prevents accuracy from being lowered.'),(15,'Tangled Feet','Doubles evasion when confused.'),(16,'Big Pecks','Protects against Defense drops.'),(17,'Guts','Increases Attack to 1.5× with a major status ailment.'),(18,'Hustle','Strengthens physical moves to inflict 1.5× damage, but decreases their accuracy to 0.8×.'),(19,'Intimidate','Lowers opponents\' Attack one stage upon entering battle.'),(20,'Unnerve','Prevents opposing Pokémon from eating held Berries.'),(21,'Static','Has a 30% chance of paralyzing attacking Pokémon on contact.'),(22,'Lightning Rod','Redirects single-target Electric moves to this Pokémon where possible.  Absorbs Electric moves, raising Special Attack one stage.'),(23,'Sand Veil','Increases evasion to 1.25× during a sandstorm.  Protects against sandstorm damage.'),(24,'Sand Rush','Doubles Speed during a sandstorm.  Protects against sandstorm damage.'),(25,'Poison Point','Has a 30% chance of poisoning attacking Pokémon on contact.'),(26,'Rivalry','Increases damage inflicted to 1.25× against Pokémon of the same gender, but decreases damage to 0.75× against the opposite gender.'),(27,'Sheer Force','Strengthens moves with extra effects to 1.3× their power, but prevents their extra effects.'),(28,'Cute Charm','Has a 30% chance of infatuating attacking Pokémon on contact.'),(29,'Magic Guard','Protects against damage not directly caused by a move.'),(30,'Friend Guard','Decreases all direct damage taken by friendly Pokémon to 0.75×.'),(31,'Unaware','Ignores other Pokémon\'s stat modifiers for damage and accuracy calculation.'),(32,'Flash Fire','Protects against Fire moves.  Once one has been blocked, the Pokémon\'s own Fire moves inflict 1.5× damage until it leaves battle.'),(33,'Drought','Summons strong sunlight that lasts indefinitely upon entering battle.'),(34,'Competitive','Raises Special Attack by two stages upon having any stat lowered.'),(35,'Frisk','Reveals an opponent\'s held item upon entering battle.'),(36,'Inner Focus','Prevents flinching.'),(37,'Infiltrator','Bypasses Light Screen, Reflect, and Safeguard.'),(38,'Stench','Has a 10% chance of making target Pokémon flinch with each hit.'),(39,'Effect Spore','Has a 30% chance of inflcting either paralysis, poison, or sleep on attacking Pokémon on contact.'),(40,'Dry Skin','Causes 1/8 max HP in damage each turn during strong sunlight, but heals for 1/8 max HP during rain.  Increases damage from Fire moves to 1.25×, but absorbs Water moves, healing for 1/4 max HP.'),(41,'Damp','Prevents Self-Destruct, Explosion, and Aftermath from working while the Pokémon is in battle.'),(42,'Wonder Skin','Lowers incoming non-damaging moves\' base accuracy to exactly 50%.'),(43,'Arena Trap','Prevents opponents from fleeing or switching out.  Eluded by Flying-types and Pokémon in the air.'),(44,'Sand Force','Strengthens Rock, Ground, and Steel moves to 1.3× their power during a sandstorm.  Protects against sandstorm damage.'),(45,'Pickup','Picks up other Pokémon\'s used and Flung held items.  May also pick up an item after battle.'),(46,'Technician','Strengthens moves of 60 base power or less to 1.5× their power.'),(47,'Limber','Prevents paralysis.'),(48,'Cloud Nine','Negates all effects of weather, but does not prevent the weather itself.'),(49,'Swift Swim','Doubles Speed during rain.'),(50,'Vital Spirit','Prevents sleep.'),(51,'Anger Point','Raises Attack to the maximum of six stages upon receiving a critical hit.'),(52,'Defiant','Raises Attack two stages upon having any stat lowered.'),(53,'Justified','Raises Attack one stage upon taking damage from a Dark move.'),(54,'Water Absorb','Absorbs Water moves, healing for 1/4 max HP.'),(55,'Synchronize','Copies burns, paralysis, and poison received onto the Pokémon that inflicted them.'),(56,'No Guard','Ensures all moves used by and against the Pokémon hit.'),(57,'Steadfast','Raises Speed one stage upon flinching.'),(58,'Gluttony','Makes the Pokémon eat any held Berry triggered by low HP below 1/2 its max HP.'),(59,'Clear Body','Prevents stats from being lowered by other Pokémon.'),(60,'Liquid Ooze','Damages opponents using leeching moves for as much as they would heal.'),(61,'Rock Head','Protects against recoil damage.'),(62,'Sturdy','Prevents being KOed from full HP, leaving 1 HP instead.  Protects against the one-hit KO moves regardless of HP.'),(63,'Flame Body','Has a 30% chance of burning attacking Pokémon on contact.'),(64,'Oblivious','Prevents infatuation and protects against Captivate.'),(65,'Own Tempo','Prevents confusion.'),(66,'Regenerator','Heals for 1/3 max HP upon switching out.'),(67,'Magnet Pull','Prevents Steel opponents from fleeing or switching out.'),(68,'Analytic','Strengthens moves to 1.3× their power when moving last.'),(69,'Early Bird','Makes sleep pass twice as quickly.'),(70,'Thick Fat','Halves damage from Fire and Ice moves.'),(71,'Hydration','Cures any major status ailment after each turn during rain.'),(72,'Ice Body','Heals for 1/16 max HP after each turn during hail.  Protects against hail damage.'),(73,'Sticky Hold','Prevents a held item from being removed by other Pokémon.'),(74,'Poison Touch','Has a 30% chance of poisoning target Pokémon upon contact.'),(75,'Shell Armor','Protects against critical hits.'),(76,'Skill Link','Extends two-to-five-hit moves and Triple Kick to their full length every time.'),(77,'Overcoat','Protects against damage from weather.'),(78,'Levitate','Evades Ground moves.'),(79,'Cursed Body','Has a 30% chance of Disabling any move that hits the Pokémon.'),(80,'Weak Armor','Raises Speed and lowers Defense by one stage each upon being hit by a physical move.'),(81,'Insomnia','Prevents sleep.'),(82,'Forewarn','Reveals the opponents\' strongest move upon entering battle.'),(83,'Hyper Cutter','Prevents Attack from being lowered by other Pokémon.'),(84,'Soundproof','Protects against sound-based moves.'),(85,'Aftermath','Damages the attacker for 1/4 its max HP when knocked out by a contact move.'),(86,'Harvest','Has a 50% chance of restoring a used Berry after each turn if the Pokémon has held no items in the meantime.'),(87,'Battle Armor','Protects against critical hits.'),(88,'Reckless','Strengthens recoil moves to 1.2× their power.'),(89,'Unburden','Doubles Speed upon using or losing a held item.'),(90,'Iron Fist','Strengthens punch-based moves to 1.2× their power.'),(91,'Neutralizing Gas','Neutralizes abilities of all Pokémon in battle.'),(92,'Natural Cure','Cures any major status ailment upon switching out.'),(93,'Serene Grace','Doubles the chance of moves\' extra effects occurring.'),(94,'Healer','Has a 30% chance of curing each adjacent ally of any major status ailment after each turn.'),(95,'Leaf Guard','Protects against major status ailments during strong sunlight.'),(96,'Scrappy','Lets the Pokémon\'s Normal and Fighting moves hit Ghost Pokémon.'),(97,'Water Veil','Prevents burns.'),(98,'Illuminate','Doubles the wild encounter rate.'),(99,'Filter','Decreases damage taken from super-effective moves by 1/4.'),(100,'Mold Breaker','Bypasses targets\' abilities if they could hinder or prevent a move.'),(101,'Moxie','Raises Attack one stage upon KOing a Pokémon.'),(102,'Rattled','Raises Speed one stage upon being hit by a Dark, Ghost, or Bug move.'),(103,'Imposter','Transforms upon entering battle.'),(104,'Adaptability','Increases the same-type attack bonus from 1.5× to 2×.'),(105,'Anticipation','Notifies all trainers upon entering battle if an opponent has a super-effective move, Self-Destruct, Explosion, or a one-hit KO move.'),(106,'Volt Absorb','Absorbs Electric moves, healing for 1/4 max HP.'),(107,'Quick Feet','Increases Speed to 1.5× with a major status ailment.'),(108,'Trace','Copies an opponent\'s ability upon entering battle.'),(109,'Download','Raises the attack stat corresponding to the opponents\' weaker defense one stage upon entering battle.'),(110,'Pressure','Increases the PP cost of moves targetting the Pokémon by one.'),(111,'Immunity','Prevents poison.'),(112,'Snow Cloak','Increases evasion to 1.25× during hail.  Protects against hail damage.'),(113,'Marvel Scale','Increases Defense to 1.5× with a major status ailment.'),(114,'Multiscale','Halves damage taken from full HP.');
