--
-- Table structure for table `pokemon`
--

DROP TABLE IF EXISTS `pokemon`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pokemon` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `height` double NOT NULL,
  `weight` double NOT NULL,
  `n_regional` smallint unsigned NOT NULL,
  `n_international` smallint unsigned NOT NULL,
  `generation` tinyint unsigned NOT NULL,
  `description` text NOT NULL,
  `male` decimal(5,2) DEFAULT NULL,
  `female` decimal(5,2) DEFAULT NULL,
  `image` varchar(50) NOT NULL,
  `evolution_level` tinyint DEFAULT NULL,
  `evolution_stone` tinyint(1) NOT NULL DEFAULT '0',
  `evolution_trade` tinyint(1) NOT NULL DEFAULT '0',
  `evolution_friendship` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `pokemon_name_unique` (`name`),
  UNIQUE KEY `pokemon_n_regional_unique` (`n_regional`),
  UNIQUE KEY `pokemon_n_international_unique` (`n_international`),
  KEY `pokemon_generation_index` (`generation`),
  KEY `pokemon_evolution_level_index` (`evolution_level`),
  KEY `pokemon_evolution_stone_index` (`evolution_stone`),
  KEY `pokemon_evolution_trade_index` (`evolution_trade`),
  KEY `pokemon_evolution_friendship_index` (`evolution_friendship`)
) ENGINE=InnoDB AUTO_INCREMENT=154 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

