INSERT INTO `pokemon` VALUES (1,'Bulbasaur',0.7,6.9,1,1,1,'A strange seed was planted on its back at birth. The plant sprouts and grows with this POKéMON.',87.50,12.50,'bulbasaur.png',16,0,0,0),(2,'Ivysaur',1,13,2,2,1,'When the bulb on its back grows large, it appears to lose the ability to stand on its hind legs.',87.50,12.50,'ivysaur.png',32,0,0,0),(3,'Venusaur',2,100,3,3,1,'The plant blooms when it is absorbing solar energy. It stays on the move to seek sunlight.',87.50,12.50,'venusaur.png',NULL,0,0,0),(4,'Charmander',0.6,8.5,4,4,1,'Obviously prefers hot places. When it rains, steam is said to spout from the tip of its tail.',87.50,12.50,'charmander.png',16,0,0,0),(5,'Charmeleon',1.1,19,5,5,1,'When it swings its burning tail, it elevates the temperature to unbearably high levels.',87.50,12.50,'charmeleon.png',36,0,0,0),(6,'Charizard',1.7,90.5,6,6,1,'Spits fire that is hot enough to melt boulders. Known to cause forest fires unintentionally.',87.50,12.50,'charizard.png',NULL,0,0,0),(7,'Squirtle',0.5,9,7,7,1,'After birth, its back swells and hardens into a shell. Powerfully sprays foam from its mouth.',87.50,12.50,'squirtle.png',16,0,0,0),(8,'Wartortle',1,22.5,8,8,1,'Often hides in water to stalk unwary prey. For swimming fast, it moves its ears to maintain balance.',87.50,12.50,'wartortle.png',36,0,0,0),(9,'Blastoise',1.6,85.5,9,9,1,'A brutal POKéMON with pressurized water jets on its shell. They are used for high speed tackles.',87.50,12.50,'blastoise.png',NULL,0,0,0),(10,'Caterpie',0.3,2.9,10,10,1,'Its short feet are tipped with suction pads that enable it to tirelessly climb slopes and walls.',50.00,50.00,'caterpie.png',7,0,0,0),(11,'Metapod',0.7,9.9,11,11,1,'This POKéMON is vulnerable to attack while its shell is soft, exposing its weak and tender body.',50.00,50.00,'metapod.png',10,0,0,0),(12,'Butterfree',1.1,32,12,12,1,'In battle, it flaps its wings at high speed to release highly toxic dust into the air.',50.00,50.00,'butterfree.png',NULL,0,0,0),(13,'Weedle',0.3,3.2,13,13,1,'Often found in forests, eating leaves. It has a sharp venomous stinger on its head.',50.00,50.00,'weedle.png',7,0,0,0),(14,'Kakuna',0.6,10,14,14,1,'Almost incapable of moving, this POKéMON can only harden its shell to protect itself from predators.',50.00,50.00,'kakuna.png',10,0,0,0),(15,'Beedrill',1,29.5,15,15,1,'Flies at high speed and attacks using its large venomous stingers on its forelegs and tail.',50.00,50.00,'beedrill.png',NULL,0,0,0),(16,'Pidgey',0.3,1.8,16,16,1,'A common sight in forests and woods. It flaps its wings at ground level to kick up blinding sand.',50.00,50.00,'pidgey.png',18,0,0,0),(17,'Pidgeotto',1.1,30,17,17,1,'Very protective of its sprawling territorial area, this POKéMON will fiercely peck at any intruder.',50.00,50.00,'pidgeotto.png',36,0,0,0),(18,'Pidgeot',1.5,39.5,18,18,1,'When hunting, it skims the surface of water at high speed to pick off unwary prey such as MAGIKARP.',50.00,50.00,'pidgeot.png',NULL,0,0,0),(19,'Rattata',0.3,3.5,19,19,1,'Bites anything when it attacks. Small and very quick, it is a common sight in many places.',50.00,50.00,'rattata.png',20,0,0,0),(20,'Raticate',0.7,18.5,20,20,1,'It uses its whis­ kers to maintain its balance. It apparently slows down if they are cut off.',50.00,50.00,'raticate.png',NULL,0,0,0),(21,'Spearow',0.3,2,21,21,1,'Eats bugs in grassy areas. It has to flap its short wings at high speed to stay airborne.',50.00,50.00,'spearow.png',20,0,0,0),(22,'Fearow',1.2,38,22,22,1,'With its huge and magnificent wings, it can keep aloft without ever having to land for rest.',50.00,50.00,'fearow.png',NULL,0,0,0),(23,'Ekans',2,6.9,23,23,1,'Moves silently and stealthily. Eats the eggs of birds, such as PIDGEY and SPEAROW, whole.',50.00,50.00,'ekans.png',22,0,0,0),(24,'Arbok',3.5,65,24,24,1,'It is rumored that the ferocious warning markings on its belly differ from area to area.',50.00,50.00,'arbok.png',NULL,0,0,0),(25,'Pikachu',0.4,6,25,25,1,'When several of these POKéMON gather, their electricity could build and cause lightning storms.',50.00,50.00,'pikachu.png',NULL,1,0,0),(26,'Raichu',0.8,30,26,26,1,'Its long tail serves as a ground to protect itself from its own high voltage power.',50.00,50.00,'raichu.png',NULL,0,0,0),(27,'Sandshrew',0.6,12,27,27,1,'Burrows deep underground in arid locations far from water. It only emerges to hunt for food.',50.00,50.00,'sandshrew.png',22,1,0,0),(28,'Sandslash',1,29.5,28,28,1,'Curls up into a spiny ball when threatened. It can roll while curled up to attack or escape.',50.00,50.00,'sandslash.png',NULL,0,0,0),(29,'Nidoran-f',0.4,7,29,29,1,'Although small, its venomous barbs render this POKéMON dangerous. The female has smaller horns.',0.00,100.00,'nidoran-f.png',16,0,0,0),(30,'Nidorina',0.8,20,30,30,1,'The female\'s horn develops slowly. Prefers physical attacks such as clawing and biting.',0.00,100.00,'nidorina.png',NULL,1,0,0),(31,'Nidoqueen',1.3,60,31,31,1,'Its hard scales provide strong protection. It uses its hefty bulk to execute powerful moves.',0.00,100.00,'nidoqueen.png',NULL,0,0,0),(32,'Nidoran-m',0.5,9,32,32,1,'Stiffens its ears to sense danger. The larger its horns, the more powerful its secreted venom.',100.00,0.00,'nidoran-m.png',16,0,0,0),(33,'Nidorino',0.9,19.5,33,33,1,'An aggressive POKéMON that is quick to attack. The horn on its head secretes a powerful venom.',100.00,0.00,'nidorino.png',NULL,1,0,0),(34,'Nidoking',1.4,62,34,34,1,'It uses its powerful tail in battle to smash, constrict, then break the prey\'s bones.',100.00,0.00,'nidoking.png',NULL,0,0,0),(35,'Clefairy',0.6,7.5,35,35,1,'Its magical and cute appeal has many admirers. It is rare and found only in certain areas.',25.00,75.00,'clefairy.png',NULL,1,0,0),(36,'Clefable',1.3,40,36,36,1,'A timid fairy POKéMON that is rarely seen. It will run and hide the moment it senses people.',25.00,75.00,'clefable.png',NULL,0,0,0),(37,'Vulpix',0.6,9.9,37,37,1,'At the time of birth, it has just one tail. The tail splits from its tip as it grows older.',25.00,75.00,'vulpix.png',NULL,1,0,0),(38,'Ninetales',1.1,19.9,38,38,1,'Very smart and very vengeful. Grabbing one of its many tails could result in a 1000-year curse.',25.00,75.00,'ninetales.png',NULL,0,0,0),(39,'Jigglypuff',0.5,5.5,39,39,1,'When its huge eyes light up, it sings a mysteriously soothing melody that lulls its enemies to sleep.',25.00,75.00,'jigglypuff.png',NULL,1,0,0),(40,'Wigglytuff',1,12,40,40,1,'The body is soft and rubbery. When angered, it will suck in air and inflate itself to an enormous size.',25.00,75.00,'wigglytuff.png',NULL,0,0,0),(41,'Zubat',0.8,7.5,41,41,1,'Forms colonies in perpetually dark places. Uses ultrasonic waves to identify and approach targets.',50.00,50.00,'zubat.png',22,0,0,0),(42,'Golbat',1.6,55,42,42,1,'Once it strikes, it will not stop draining energy from the victim even if it gets too heavy to fly.',50.00,50.00,'golbat.png',NULL,0,0,1),(43,'Oddish',0.5,5.4,43,43,1,'During the day, it keeps its face buried in the ground. At night, it wanders around sowing its seeds.',50.00,50.00,'oddish.png',21,0,0,0),(44,'Gloom',0.8,8.6,44,44,1,'The fluid that oozes from its mouth isn\'t drool. It is a nectar that is used to attract prey.',50.00,50.00,'gloom.png',NULL,1,0,0),(45,'Vileplume',1.2,18.6,45,45,1,'The larger its petals, the more toxic pollen it contains. Its big head is heavy and hard to hold up.',50.00,50.00,'vileplume.png',NULL,0,0,0),(46,'Paras',0.3,5.4,46,46,1,'Burrows to suck tree roots. The mushrooms on its back grow by draw­ ing nutrients from the bug host.',50.00,50.00,'paras.png',24,0,0,0),(47,'Parasect',1,29.5,47,47,1,'A host-parasite pair in which the parasite mushroom has taken over the host bug. Prefers damp places.',50.00,50.00,'parasect.png',NULL,0,0,0),(48,'Venonat',1,30,48,48,1,'Lives in the shadows of tall trees where it eats insects. It is attracted by light at night.',50.00,50.00,'venonat.png',31,0,0,0),(49,'Venomoth',1.5,12.5,49,49,1,'The dust-like scales covering its wings are color coded to indicate the kinds of poison it has.',50.00,50.00,'venomoth.png',NULL,0,0,0),(50,'Diglett',0.2,0.8,50,50,1,'Lives about one yard underground where it feeds on plant roots. It sometimes appears above ground.',50.00,50.00,'diglett.png',26,0,0,0),(51,'Dugtrio',0.7,33.3,51,51,1,'A team of DIGLETT triplets. It triggers huge earthquakes by burrowing 60 miles underground.',50.00,50.00,'dugtrio.png',NULL,0,0,0),(52,'Meowth',0.4,4.2,52,52,1,'Adores circular objects. Wanders the streets on a nightly basis to look for dropped loose change.',50.00,50.00,'meowth.png',28,0,0,1),(53,'Persian',1,32,53,53,1,'Although its fur has many admirers, it is tough to raise as a pet because of its fickle meanness.',50.00,50.00,'persian.png',NULL,0,0,0),(54,'Psyduck',0.8,19.6,54,54,1,'While lulling its enemies with its vacant look, this wily POKéMON will use psychokinetic powers.',50.00,50.00,'psyduck.png',33,0,0,0),(55,'Golduck',1.7,76.6,55,55,1,'Often seen swim­ ming elegantly by lake shores. It is often mistaken for the Japanese monster, Kappa.',50.00,50.00,'golduck.png',NULL,0,0,0),(56,'Mankey',0.5,28,56,56,1,'Extremely quick to anger. It could be docile one moment then thrashing away the next instant.',50.00,50.00,'mankey.png',28,0,0,0),(57,'Primeape',1,32,57,57,1,'Always furious and tenacious to boot. It will not abandon chasing its quarry until it is caught.',50.00,50.00,'primeape.png',NULL,0,0,0),(58,'Growlithe',0.7,19,58,58,1,'Very protective of its territory. It will bark and bite to repel intruders from its space.',75.00,25.00,'growlithe.png',NULL,1,0,0),(59,'Arcanine',1.9,155,59,59,1,'A POKéMON that has been admired since the past for its beauty. It runs agilely as if on wings.',75.00,25.00,'arcanine.png',NULL,0,0,0),(60,'Poliwag',0.6,12.4,60,60,1,'Its newly grown legs prevent it from running. It appears to prefer swimming than trying to stand.',50.00,50.00,'poliwag.png',25,0,0,0),(61,'Poliwhirl',1,20,61,61,1,'Capable of living in or out of water. When out of water, it sweats to keep its body slimy.',50.00,50.00,'poliwhirl.png',NULL,1,1,0),(62,'Poliwrath',1.3,54,62,62,1,'An adept swimmer at both the front crawl and breast stroke. Easily overtakes the best human swimmers.',50.00,50.00,'poliwrath.png',NULL,0,0,0),(63,'Abra',0.9,19.5,63,63,1,'Using its ability to read minds, it will identify impending danger and TELEPORT to safety.',75.00,25.00,'abra.png',16,0,0,0),(64,'Kadabra',1.3,56.5,64,64,1,'It emits special alpha waves from its body that induce headaches just by being close by.',75.00,25.00,'kadabra.png',NULL,0,1,0),(65,'Alakazam',1.5,48,65,65,1,'Its brain can out­ perform a super­ computer. Its intelligence quotient is said to be 5,000.',75.00,25.00,'alakazam.png',NULL,0,0,0),(66,'Machop',0.8,19.5,66,66,1,'Loves to build its muscles. It trains in all styles of martial arts to become even stronger.',75.00,25.00,'machop.png',28,0,0,0),(67,'Machoke',1.5,70.5,67,67,1,'Its muscular body is so powerful, it must wear a power save belt to be able to regulate its motions.',75.00,25.00,'machoke.png',NULL,0,1,0),(68,'Machamp',1.6,130,68,68,1,'Using its heavy muscles, it throws powerful punches that can send the victim clear over the horizon.',75.00,25.00,'machamp.png',NULL,0,0,0),(69,'Bellsprout',0.7,4,69,69,1,'A carnivorous POKéMON that traps and eats bugs. It uses its root feet to soak up needed moisture.',50.00,50.00,'bellsprout.png',21,0,0,0),(70,'Weepinbell',1,6.4,70,70,1,'It spits out POISONPOWDER to immobilize the enemy and then finishes it with a spray of ACID.',50.00,50.00,'weepinbell.png',NULL,1,0,0),(71,'Victreebel',1.7,15.5,71,71,1,'Said to live in huge colonies deep in jungles, although no one has ever returned from there.',50.00,50.00,'victreebel.png',NULL,0,0,0),(72,'Tentacool',0.9,45.5,72,72,1,'Drifts in shallow seas. Anglers who hook them by accident are often punished by its stinging acid.',50.00,50.00,'tentacool.png',30,0,0,0),(73,'Tentacruel',1.6,55,73,73,1,'The tentacles are normally kept short. On hunts, they are extended to ensnare and immobilize prey.',50.00,50.00,'tentacruel.png',NULL,0,0,0),(74,'Geodude',0.4,20,74,74,1,'Found in fields and mountains. Mistaking them for boulders, people often step or trip on them.',50.00,50.00,'geodude.png',25,0,0,0),(75,'Graveler',1,105,75,75,1,'Rolls down slopes to move. It rolls over any obstacle without slowing or changing its direction.',50.00,50.00,'graveler.png',NULL,0,1,0),(76,'Golem',1.4,300,76,76,1,'Its boulder-like body is extremely hard. It can easily withstand dynamite blasts without damage.',50.00,50.00,'golem.png',NULL,0,0,0),(77,'Ponyta',1,30,77,77,1,'Its hooves are 10 times harder than diamonds. It can trample anything completely flat in little time.',50.00,50.00,'ponyta.png',40,0,0,0),(78,'Rapidash',1.7,95,78,78,1,'Very competitive, this POKéMON will chase anything that moves fast in the hopes of racing it.',50.00,50.00,'rapidash.png',NULL,0,0,0),(79,'Slowpoke',1.2,36,79,79,1,'Incredibly slow and dopey. It takes 5 seconds for it to feel pain when under attack.',50.00,50.00,'slowpoke.png',37,1,1,0),(80,'Slowbro',1.6,78.5,80,80,1,'The SHELLDER that is latched onto SLOWPOKE\'s tail is said to feed on the host\'s left over scraps.',50.00,50.00,'slowbro.png',NULL,0,0,0),(81,'Magnemite',0.3,6,81,81,1,'Uses anti-gravity to stay suspended. Appears without warning and uses THUNDER WAVE and similar moves.',NULL,NULL,'magnemite.png',30,0,0,0),(82,'Magneton',1,60,82,82,1,'Formed by several MAGNEMITEs linked together. They frequently appear when sunspots flare up.',NULL,NULL,'magneton.png',NULL,1,0,0),(83,'Farfetchd',0.8,15,83,83,1,'The sprig of green onions it holds is its weapon. It is used much like a metal sword.',50.00,50.00,'farfetchd.png',NULL,0,0,0),(84,'Doduo',1.4,39.2,84,84,1,'A bird that makes up for its poor flying with its fast foot speed. Leaves giant footprints.',50.00,50.00,'doduo.png',31,0,0,0),(85,'Dodrio',1.8,85.2,85,85,1,'Uses its three brains to execute complex plans. While two heads sleep, one head stays awake.',50.00,50.00,'dodrio.png',NUL